// @vitest-environment node

import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { convert } from "./converter.js";

// Fixtures are generated by test-corpus/create-fixtures.mjs (pdf-lib) and committed.
const fixturesDir = resolve(dirname(fileURLToPath(import.meta.url)), "../../../test-corpus/fixtures");

async function convertFixture(name: string): Promise<string> {
  const bytes = await readFile(resolve(fixturesDir, name));
  const result = await convert(new Uint8Array(bytes).buffer);
  expect(result.status).toBe("success");
  return result.markdown;
}

function markdownLinks(markdown: string): Array<{ text: string; url: string }> {
  return [...markdown.matchAll(/\[([^\]]*)\]\(([^)\s]+)\)/g)].map((m) => ({ text: m[1], url: m[2] }));
}

describe("page-scoped link matching", () => {
  it("links text only on the page that carries the annotation", async () => {
    const markdown = await convertFixture("links-same-position.pdf");
    const homeLinks = markdownLinks(markdown).filter((l) => l.url === "https://example.com/home");

    // "Project homepage" is drawn at the same spot on pages 1–3; only page 2 has the link.
    expect(homeLinks).toEqual([{ text: "Project homepage", url: "https://example.com/home" }]);
    expect(markdown.match(/Project homepage/g)).toHaveLength(3);
  });

  it("merges consecutive items that share a URL into one link", async () => {
    const markdown = await convertFixture("links-same-position.pdf");
    expect(markdown).toContain("[Read the docs](https://example.com/docs)");

    // No two links side by side on a line with the same URL.
    expect(markdown).not.toMatch(/\]\(([^)\s]+)\)[ \t]*\[[^\]]*\]\(\1\)/);
  });

  it("does not wrap a lone punctuation item that only sits inside a wider link", async () => {
    const markdown = await convertFixture("links-same-position.pdf");
    expect(markdown).not.toContain("[(]");
    expect(markdown).toContain("[see appendix](https://example.com/appendix)");
  });
});

describe("header/footer stripping stays in the header and footer bands", () => {
  it("removes footer page numbers but keeps standalone numbers in the body", async () => {
    const markdown = await convertFixture("header-footer-numbers.pdf");

    // Running header is stripped.
    expect(markdown).not.toContain("Example Annual Report");

    // Body numbers survive: TOC page numbers and table cells.
    for (const n of ["17", "23", "2022", "2023", "19"]) {
      expect(markdown).toMatch(new RegExp(`(^|[^\\d])${n}([^\\d]|$)`));
    }
    expect(markdown.match(/(^|[^\d])17([^\d]|$)/g)?.length).toBe(2);

    // Footer page numbers 1–5 are gone: no line is just a number.
    expect(markdown.split("\n").filter((line) => /^\s*\d\s*$/.test(line))).toEqual([]);
  });
});

describe("binary input types", () => {
  const fixture = () => readFile(resolve(fixturesDir, "links-same-position.pdf"));

  it("accepts a Node Buffer as returned by fs.readFile", async () => {
    const buffer = await fixture();
    const result = await convert(buffer);
    expect(result.status).toBe("success");
    expect(result.markdown).toContain("Project homepage");
    expect(buffer.byteLength).toBeGreaterThan(0);
  });

  it("accepts a Uint8Array view and leaves the caller's buffer attached", async () => {
    const bytes = new Uint8Array(await fixture());
    const length = bytes.buffer.byteLength;
    const result = await convert(bytes);
    expect(result.status).toBe("success");
    expect(bytes.buffer.byteLength).toBe(length);
  });

  it("accepts an ArrayBuffer and leaves it attached", async () => {
    const arrayBuffer = new Uint8Array(await fixture()).buffer;
    const length = arrayBuffer.byteLength;
    const result = await convert(arrayBuffer);
    expect(result.status).toBe("success");
    expect(arrayBuffer.byteLength).toBe(length);
  });

  it("returns parse_failed, not a throw, for non-PDF bytes in a Buffer", async () => {
    const result = await convert(Buffer.from("not a pdf"));
    expect(result.status).toBe("failed");
    expect(result.messages[0]?.code).toBe("parse_failed");
  });
});
